{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.chart2_myntra AS WITH asof_window AS ( SELECT MAX(TO_DATE(ORDER_CREATED_DATE::VARCHAR, \'YYYYMMDD\')) AS window_end FROM snitch_db.maplemonk.s3_soh_sales ), grn_real AS ( SELECT g.SKU_CODE, g.RECEIVED_QUANTITY, g.RECEIVED_AT, m.STYLE_ID FROM snitch_db.maplemonk.s3_myntra_historical_grn g JOIN snitch_db.maplemonk.myntra_sku_master m ON m.SKU_CODE = g.SKU_CODE WHERE m.STYLE_ID IS NOT NULL ), style_grn AS ( SELECT STYLE_ID, SUM(CASE WHEN RECEIVED_AT >= \'2026-04-01\' THEN RECEIVED_QUANTITY ELSE 0 END) AS qty_grned, MIN(CASE WHEN RECEIVED_AT >= \'2026-04-01\' THEN RECEIVED_AT END) AS style_grn_date, SUM(CASE WHEN RECEIVED_AT < \'2026-04-01\' THEN RECEIVED_QUANTITY ELSE 0 END) AS pre_fy_grn_units FROM grn_real GROUP BY STYLE_ID HAVING SUM(CASE WHEN RECEIVED_AT >= \'2026-04-01\' THEN RECEIVED_QUANTITY ELSE 0 END) > 0 ), ro_real AS ( SELECT r.SKU_CODE, r.RO_TYPE, r.REJECTED_ON, m.STYLE_ID FROM snitch_db.maplemonk.s3_myntra_historic_ro r JOIN snitch_db.maplemonk.myntra_sku_master m ON m.SKU_CODE = r.SKU_CODE WHERE m.STYLE_ID IS NOT NULL ), style_rtv AS ( SELECT STYLE_ID, COUNT(CASE WHEN REJECTED_ON >= \'2026-04-01\' AND RO_TYPE = \'SOR_ITEM\' THEN 1 END) AS rtv_units FROM ro_real GROUP BY STYLE_ID ), style_sales_dates AS ( SELECT STYLE_ID, SALES, TO_DATE(ORDER_CREATED_DATE::VARCHAR, \'YYYYMMDD\') AS order_date FROM snitch_db.maplemonk.s3_soh_sales WHERE STYLE_ID IS NOT NULL AND TO_DATE(ORDER_CREATED_DATE::VARCHAR, \'YYYYMMDD\') >= TO_DATE(\'2026-04-01\') ), style_sold_after_grn AS ( SELECT d.STYLE_ID, SUM(d.SALES) AS qty_sold_after_grn FROM style_sales_dates d JOIN style_grn g ON g.STYLE_ID = d.STYLE_ID WHERE d.order_date >= g.style_grn_date GROUP BY d.STYLE_ID ), style_ros AS ( SELECT d.STYLE_ID, SUM(CASE WHEN d.order_date >= DATEADD(day, -6, a.window_end) THEN d.SALES ELSE 0 END) / 7.0 AS ros_7, SUM(CASE WHEN d.order_date >= DATEADD(day, -13, a.window_end) THEN d.SALES ELSE 0 END) / 14.0 AS ros_14, SUM(CASE WHEN d.order_date >= DATEADD(day, -27, a.window_end) THEN d.SALES ELSE 0 END) / 28.0 AS ros_28 FROM style_sales_dates d CROSS JOIN asof_window a GROUP BY d.STYLE_ID ), style_soh AS ( SELECT STYLE_ID, SUM(SOH) AS current_soh FROM snitch_db.maplemonk.s3_soh_inventory WHERE STYLE_ID IS NOT NULL GROUP BY STYLE_ID ), style_in_catalog AS ( SELECT DISTINCT STYLE_ID FROM snitch_db.maplemonk.myntra_sku_master WHERE STYLE_ID IS NOT NULL ), m_calc AS ( SELECT g.STYLE_ID AS sku, g.qty_grned, g.pre_fy_grn_units, CASE WHEN c.STYLE_ID IS NULL THEN NULL ELSE COALESCE(a.qty_sold_after_grn, 0) + COALESCE(rt.rtv_units, 0) END AS qty_sold_after_grn, s.current_soh, CASE WHEN c.STYLE_ID IS NULL THEN NULL ELSE g.qty_grned - COALESCE(a.qty_sold_after_grn, 0) - COALESCE(rt.rtv_units, 0) END AS expected_inventory, COALESCE(r.ros_7, 0) AS ros_7, COALESCE(r.ros_14, 0) AS ros_14, COALESCE(r.ros_28, 0) AS ros_28, c.STYLE_ID AS in_catalog_flag FROM style_grn g LEFT JOIN style_in_catalog c ON c.STYLE_ID = g.STYLE_ID LEFT JOIN style_sold_after_grn a ON a.STYLE_ID = g.STYLE_ID LEFT JOIN style_rtv rt ON rt.STYLE_ID = g.STYLE_ID LEFT JOIN style_soh s ON s.STYLE_ID = g.STYLE_ID LEFT JOIN style_ros r ON r.STYLE_ID = g.STYLE_ID ) SELECT \'MYNTRA\' AS channel, sku, qty_grned, qty_sold_after_grn, current_soh, expected_inventory, CASE WHEN in_catalog_flag IS NULL OR current_soh IS NULL OR expected_inventory IS NULL THEN NULL WHEN expected_inventory <= 0 THEN NULL WHEN expected_inventory < 10 OR expected_inventory < qty_grned * 0.05 THEN NULL ELSE ROUND((current_soh - expected_inventory) / expected_inventory * 100, 2) END AS discrepancy_pct, CASE WHEN in_catalog_flag IS NULL OR current_soh IS NULL OR expected_inventory IS NULL THEN NULL WHEN expected_inventory < 0 THEN NULL ELSE current_soh - expected_inventory END AS variance_units, CASE WHEN in_catalog_flag IS NULL OR expected_inventory IS NULL THEN NULL WHEN expected_inventory < 0 THEN -expected_inventory ELSE 0 END AS implied_pre_window_stock, CASE WHEN in_catalog_flag IS NULL OR current_soh IS NULL THEN \'NO_INVENTORY_RECORD\' WHEN expected_inventory < 0 THEN \'PRE_WINDOW_STOCK\' WHEN expected_inventory = 0 THEN \'FULLY_DEPLETED\' WHEN expected_inventory < 10 OR expected_inventory < qty_grned * 0.05 THEN \'LOW_BASE\' ELSE \'OK\' END AS row_status, CASE WHEN in_catalog_flag IS NULL THEN NULL ELSE ros_7 END AS ros_7, CASE WHEN in_catalog_flag IS NULL THEN NULL ELSE ros_14 END AS ros_14, CASE WHEN in_catalog_flag IS NULL THEN NULL ELSE ros_28 END AS ros_28, \'SKU_LEVEL_REAL_GRN\' AS grn_grain, pre_fy_grn_units FROM m_calc ORDER BY sku;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            